import{_ as t,o as n,c as a,ak as o}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy learning-content guide","description":"Owners: Sherwin (Design Lead) and Sean (Docs Lead). October 12, 2026.","frontmatter":{"title":"Chainy learning-content guide","description":"Owners: Sherwin (Design Lead) and Sean (Docs Lead). October 12, 2026.","source":"docs/learning-foundations.md","category":"Other documents","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/learning-foundations.md","filePath":"content/docs/learning-foundations.md"}'),r={name:"content/docs/learning-foundations.md"};function i(s,e,c,d,l,h){return n(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="chainy-learning-content-guide">Chainy learning-content guide<a class="header-anchor" href="#chainy-learning-content-guide" aria-label="Link to this section">​</a></h1><p>Owners: Sherwin (Design Lead) and Sean (Docs Lead). October 12, 2026.</p><p>The subject scope remains introductory Web3, Blockchain and AI for ages 12–17. The delivery formats are now Quiz, Wordle and BlockMatch within explorable learning levels. The previous nine-lesson curriculum and its simulation/classifier/agent exercises are <a href="/Chainy-Docs/content/docs/archive/pre-2026-10-12/docs/learning-foundations.html">historical</a>.</p><h2 id="one-small-content-sheet">One small content sheet<a class="header-anchor" href="#one-small-content-sheet" aria-label="Link to this section">​</a></h2><p>For every activity, record: <strong>topic → one learning objective → explanation/example → player task → correct answer or matching rule → feedback → source</strong>. Add the mode and a stable content identifier so Christian can connect the content to progress.</p><table><thead><tr><th>Mode</th><th>Useful learning role</th><th>What the author must supply</th></tr></thead><tbody><tr><td>Quiz</td><td>Check understanding and choices</td><td>Question, choices, correct answer and explanation for each answer</td></tr><tr><td>Wordle</td><td>Reinforce a taught term</td><td>Allowed word, plain-language definition/context, hint and explanation after play</td></tr><tr><td>BlockMatch</td><td>Practice a meaningful relationship</td><td>Matchable items, the relation that makes a match correct, examples/non-examples and explanation</td></tr></tbody></table><p>Word spelling, speed or a high matching score alone does not establish concept understanding. Use a short explanation or follow-up question where needed.</p><h2 id="writing-and-review">Writing and review<a class="header-anchor" href="#writing-and-review" aria-label="Link to this section">​</a></h2><p>Use familiar examples before technical terms. Keep instructions short; avoid assuming prior computer or cryptocurrency experience. Essential instructions must work without audio. Test whether players can explain what they learned, not just what they tapped.</p><p>Sherwin approves the gameplay purpose. Sean checks wording and sources. Christian checks technical accuracy and implementability; seek subject/adviser review where the team lacks expertise. Luis and Miguel check whether pictures and screens support the explanation.</p><p>Do not automatically reuse the old questions: first check whether the new game actually teaches what they ask. Freeze the final content list and answer keys before beta; record later corrections.</p><h2 id="before-content-production-expands">Before content production expands<a class="header-anchor" href="#before-content-production-expands" aria-label="Link to this section">​</a></h2><p>CH-02 freezes a short rules/content sheet for each mode. CH-06 proves one Quiz lesson. CH-09 packages the approved content for all three modes and subject areas. Content quantity follows the first completed example and available time; no fixed nine-lesson or three-world-map commitment remains.</p><p>Research pre/post questions belong to the adviser-reviewed evaluation instrument and should not be treated as interchangeable with repeated in-game practice. See <a href="/Chainy-Docs/content/docs/qa-evaluation.html">evaluation</a>.</p></div>',1)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
